use qop_wire::*;use qop_wire::extension::*;use qop_wire::production::*;use ed25519_dalek::SigningKey;use std::io::Write;
#[test]fn recovery(){let k=SigningKey::from_bytes(&[1;32]);let w=SigningKey::from_bytes(&[2;32]);let id=[3;32];let p=[4;24];let empty=Checkpoint::sign(id,&Mmr::default(),&w);let path=std::env::temp_dir().join(format!("qop-v03-{}",std::process::id()));let _=std::fs::remove_file(&path);let f=mint(&k,0,1,2,1,[5;32],GENESIS,p);let floor;{let mut d=Recovery::open(&path,k.verifying_key(),p,&empty,id,&w.verifying_key()).unwrap();assert!(Recovery::open(&path,k.verifying_key(),p,&empty,id,&w.verifying_key()).is_err());d.append(&f).unwrap();floor=Checkpoint::sign(id,d.mmr().unwrap(),&w);}std::fs::OpenOptions::new().append(true).open(&path).unwrap().write_all(&[7;23]).unwrap();{let d=Recovery::open(&path,k.verifying_key(),p,&floor,id,&w.verifying_key()).unwrap();assert_eq!(d.mmr().unwrap().len(),1);}assert_eq!(std::fs::metadata(&path).unwrap().len(),256);std::fs::write(&path,[]).unwrap();assert!(Recovery::open(&path,k.verifying_key(),p,&floor,id,&w.verifying_key()).is_err());std::fs::remove_file(path).unwrap();}
#[test]fn seal_policy(){let ks:[SigningKey;5]=std::array::from_fn(|i|SigningKey::from_bytes(&[i as u8+1;32]));let keys=std::array::from_fn(|i|ks[i].verifying_key());let v=SigningKey::from_bytes(&[9;32]);let c=[8;32];let s=[7;32];let mut e:Vec<_>=(0..5).map(|i|Evidence::sign(i as u8,c,s,[6;32],false,&ks[i])).collect();assert_eq!(seal(&e,&keys,c,s,&v,false).status,PENDING);assert_eq!(seal(&e,&keys,c,s,&v,true).status,PENDING);for i in 0..5{e[i]=Evidence::sign(i as u8,c,s,[6;32],true,&ks[i]);}assert_eq!(seal(&e,&keys,c,s,&v,false).status,PENDING);assert_eq!(seal(&e,&keys,c,s,&v,true).status,VERIFIED);assert_eq!(seal(&e,&keys,[0;32],s,&v,true).status,PENDING);e[0].artifact[0]^=1;assert_eq!(seal(&e,&keys,c,s,&v,true).status,PENDING);assert!(ptp_bound(-10,20,5,5,30));assert!(!ptp_bound(-10,20,5,5,29));assert!(!ptp_bound(i64::MIN,u64::MAX,u64::MAX,1,100));}
